-- Loy Travel v0.12 — additive content only\n-- Adds Road to Hana candidates and treat-review spots.\n-- Does NOT delete/reset/reseed existing votes, cards, packing, Costco, or other family data.\n\n-- Road to Hana activity candidates\nwith m as (select id from trips where name='Maui 2026' limit 1),\nnew_items(name,category,short_description,status) as (values\n('Waikamoi Ridge Trail','Road to Hana · Hike','Short forest hike candidate on the Road to Hana; a good leg-stretcher without committing the family to another long hike. Re-check current trail/weather conditions before the trip.','idea'),\n('Wailua Valley State Wayside','Road to Hana · Scenic Stop','Quick scenic viewpoint over Keʻanae Valley, Koʻolau Gap and Wailua taro fields.','idea'),\n('Ke Ala Loa O Maui / Piʻilani Trail','Road to Hana · Hike','Moderate 3-mile round-trip coastal lava trail at Waiʻānapanapa; a bigger walking option if the family wants more than the black-sand beach stop.','idea')\n)\ninsert into activities(trip_id,name,category,short_description,status)\nselect m.id,n.name,n.category,n.short_description,n.status from m cross join new_items n\nwhere not exists (select 1 from activities a where a.trip_id=m.id and a.name=n.name);\n\n-- Treat-review candidates. Existing food_spots schema is preserved.\nwith m as (select id from trips where name='Maui 2026' limit 1),\nr(name,area,meal_type,cuisine,price_level,drive_minutes,safe_foods,short_description,website_url,menu_url,maps_url,status) as (values\n('Island Cream Co.','West Maui · Lahaina','Treat / dessert','Ice cream · shave ice','$',15,ARRAY[]::text[],'West Maui dessert stop with a large rotating ice-cream selection plus its Glacier Ice shave-ice station.','https://www.islandcreamco.com/','https://www.islandcreamco.com/','https://www.google.com/maps/search/?api=1&query=Island+Cream+Co+305+Keawe+St+Lahaina+Maui','idea'),\n('Peace Love Shave Ice Lāhainā','West Maui · Lahaina','Treat / dessert','Shave ice','$',15,ARRAY[]::text[],'Quick West Maui shave-ice stop; useful as a beach-day or after-dinner treat candidate.','https://peaceloveshaveice.com/','https://peaceloveshaveice.com/','https://www.google.com/maps/search/?api=1&query=Peace+Love+Shave+Ice+150+Kai+Hele+Ku+St+Lahaina+Maui','idea'),\n('Tobi''s Poke & Shave Ice · Paʻia','North Shore · Paʻia','Treat / snack','Shave ice · poke · local','$',70,ARRAY[]::text[],'Paʻia stop with Hawaiian shave ice plus poke and local food; an easy Road-to-Hāna bookend candidate.','https://tobishawaii.com/','https://tobishawaii.com/','https://www.google.com/maps/search/?api=1&query=Tobis+Poke+Shave+Ice+137+Hana+Hwy+Paia+Maui','idea'),\n('Artisan Ice Cream · Paʻia','North Shore · Paʻia','Treat / dessert','Small-batch ice cream','$',70,ARRAY[]::text[],'Family-run small-batch ice cream in Paʻia with dairy and coconut-based vegan flavors; easy to pair with a Road-to-Hāna day.','https://www.artisanpaia.com/','https://www.artisanpaia.com/icecream','https://www.google.com/maps/search/?api=1&query=Artisan+Ice+Cream+40+Baldwin+Ave+Paia+Maui','idea')\n)\ninsert into food_spots(trip_id,name,area,meal_type,cuisine,price_level,drive_minutes,safe_foods,short_description,website_url,menu_url,maps_url,status)\nselect m.id,r.name,r.area,r.meal_type,r.cuisine,r.price_level,r.drive_minutes,r.safe_foods,r.short_description,r.website_url,r.menu_url,r.maps_url,r.status\nfrom m cross join r\nwhere not exists (select 1 from food_spots f where f.trip_id=m.id and f.name=r.name);\n